import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"the stop decision: an eight-round characterization","description":"","frontmatter":{"title":"the stop decision: an eight-round characterization","type":"adr","date":"2026-10-27T00:00:00.000Z","status":"unrecorded","status_note":"measured, open. Series:\\n\\nmeasured, open.  Series:\\n`results_stop_policy.md` (r1–2) → `results_stop_advantage.md` (r6,\\nself-posterior + actor-critic) → `results_stop_valuelabel.md` (r7,\\nexpected-yield labels) → `results_stop_calibrated.md` (r8,\\nPlatt/isotonic calibration) → `results_stop_isolated.md` (r9, the\\ndelivery outside the softmax — `GatedPlayer` + the `forced_action`\\nengine hook)."},"headers":[],"relativePath":"graphopt/project/adrs/0013-the-stop-decision.md","filePath":"vendored/graphopt/project/adrs/0013-the-stop-decision.md"}'),a={name:`graphopt/project/adrs/0013-the-stop-decision.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0013-—-the-stop-decision-an-eight-round-characterization" tabindex="-1">ADR 0013 — the stop decision: an eight-round characterization <a class="header-anchor" href="#adr-0013-—-the-stop-decision-an-eight-round-characterization" aria-label="Permalink to “ADR 0013 — the stop decision: an eight-round characterization”">​</a></h1><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to “The problem”">​</a></h2><p>Should the open-game player keep evaluating pending candidates or stop? The oracle ceiling is measured: <strong>+0.026 reward/ep and 4.3× yield-per-eval</strong> (3.75 evals vs the incumbent&#39;s ~15) — real, and unreachable so far.</p><h2 id="what-eight-rounds-eliminated" tabindex="-1">What eight rounds eliminated <a class="header-anchor" href="#what-eight-rounds-eliminated" aria-label="Permalink to “What eight rounds eliminated”">​</a></h2><table tabindex="0"><thead><tr><th>blocker</th><th>round</th><th>verdict</th></tr></thead><tbody><tr><td>features</td><td>r1–2</td><td>shared-softmax stop logit drowns; supervised head degenerates to never-stop (Bayes-rational under asymmetric costs)</td></tr><tr><td>credit</td><td>r6</td><td>per-step advantage (actor-critic <code>AdvantagePlayer</code>) rescues AP vs collapse — real mechanism gain</td></tr><tr><td>observability</td><td>r6</td><td>policy&#39;s own posterior (<code>open:self</code>) ≈0.33 solo AP vs oracle labels — signal exists at zero predictor cost</td></tr><tr><td>value labels</td><td>r7</td><td><code>open:vlabel</code> expected-yield columns real, but predictors miscalibrate in magnitude held-out</td></tr><tr><td>calibration</td><td>r8</td><td>Platt/isotonic fixes magnitude (log-loss 3–5×, ECE ≤0.05) — <strong>best headless gate: isotonic <code>useful-pool</code> 0.2929 @ 12.8 evals, 26 real stops</strong></td></tr><tr><td>delivery</td><td>r9</td><td>the isolated channel (<code>forced_action</code> + <code>GatedPlayer</code>) clears both bars honestly — <code>iso-head:isotonic</code> 0.2892/AP 0.2101 @ 26 real stops, seam-free; the fold twin never-stops. Shared-softmax hypothesis <strong>confirmed for delivery</strong> — residual is evidence (all clears are tail-trims)</td></tr></tbody></table><h2 id="the-residual-blocker-stated-exactly" tabindex="-1">The residual blocker (stated exactly) <a class="header-anchor" href="#the-residual-blocker-stated-exactly" aria-label="Permalink to “The residual blocker (stated exactly)”">​</a></h2><p>At calibrated probabilities the break-even rule <em>rationally drains</em> (cost asymmetry: missed useful −1.0 vs wasted eval −0.002). No serializable arm clears both bake bars (reward ≥0.273 ∧ AP ≥0.210). What remains missing is <strong>held-out discrimination</strong> — a predictor that ranks pending candidates above chance out-of-distribution — or a stop delivery outside the shared softmax (the recurring corruption channel: five feature families all collapse AP the same way).</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Any gated decision in the game — stop included — satisfies four conditions before it can ship:</p><ol><li>Features that see the decision-relevant quantity.</li><li>Credit assigned per-step, not per-episode.</li><li>Calibrated magnitudes, held out.</li><li>A delivery channel isolated from the ranking logits.</li></ol><p>The stop policy itself stays <strong>open</strong>: no arm clears both bake bars (reward ≥0.273 ∧ AP ≥0.210), so none is adopted.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Rounds 1–8 are the measured map of which of those four was the wall at each stage — fixing one exposes the next. Recording that here is what stops a ninth round from re-trying a channel that already failed.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Adopt the isotonic <code>useful-pool</code> arm</strong> — best measured gate (0.2929 @ 12.8 evals, 26 real stops) but it does not clear both bars.</li><li><strong>Ship any shared-softmax stop head</strong> — five feature families collapsed AP the same way; the channel is the defect, not the features.</li></ul>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};